/// A phone's credentials for one host (SRD 3.6, 4.6).
///
/// [token] is a bearer credential. It lives only in `flutter_secure_storage`
/// and must never be logged or written to preferences (SEC-018).
final class PairedDevice {
  /// Creates a paired device record.
  const PairedDevice({
    required this.hostId,
    required this.deviceId,
    required this.deviceName,
    required this.token,
    required this.pinnedFingerprint,
  });

  /// The host these credentials belong to.
  final String hostId;

  /// Random UUIDv4 generated by the phone during pairing.
  final String deviceId;

  /// Human-readable phone name shown in the daemon's device list.
  final String deviceName;

  /// 256-bit bearer token issued by the daemon. Secret.
  final String token;

  /// Lowercase hex SHA-256 of the daemon certificate seen during pairing.
  final String pinnedFingerprint;

  @override
  String toString() =>
      'PairedDevice(hostId: $hostId, deviceId: $deviceId, token: <redacted>)';
}
